            console.log('V107 Tests:', passed + '/' + total, '(' + (passRate * 100).toFixed(1) + '%)');
            summary.results.forEach((r, i) => { if (!r.pass) console.log('  FAIL[' + i + ']: ' + r.msg); });
            return summary;
