            // Test 23: trial.reward multiple levels
            mockGameState.trial = { isOpen: true, clearedLevels: [1, 2, 3] };
            const reward23a = server.mcpTrialReward({ level: 1 });
            const reward23b = server.mcpTrialReward({ level: 2 });
