            v116Assert(queryStruct.entries[0].name !== undefined, 'entry has name');
            v116Assert(queryStruct.entries[0].value !== undefined, 'entry has value');
            v116Assert(queryStruct.entries[0].isPlayer !== undefined, 'entry has isPlayer');

