            v126Assert(ml1.areas && ml1.areas.length === 6, 'map.list returns 6 areas');
            v126Assert(ml1.areas[0].unlocked === true, 'area_001 unlocked by default');
            v126Assert(ml1.areas[1].unlocked === false, 'area_002 locked initially');

            // map.detail - success
