                    daoAncestorCurrentLayer: 0,  // 当前所在层数
                    daoAncestorDiscovered: [],   // 已发现的道祖
                    // 天道印记道具
                    heavenlySeals: [],           // 持有的天道印记
                    totalSealsCollected: 0,      // 累计收集的印记数
                    // 天道法则领悟系统
                    lawsComprehended: [],        // 已领悟的法则
                    currentLawInsight: 0,        // 当前法则领悟进度
                    maxLawInsight: 100,         // 最大领悟进度
